-- Phase 105 rehearsal · tests phase105-voucher-wallet.sql on the real database WITHOUT saving anything.
-- GENERATED by scripts/build-rehearsal.sh — edit the migration or tests/phase105-*.sql instead.
-- Run this whole file at once in the Supabase SQL editor. It ends with an error on purpose: that cancels
-- everything. Expected last line: ERROR: REHEARSAL REPORT (nothing was saved) … with PASS/FAIL for each check.

-- ===== setup =====
-- Phase 105 setup (runs BEFORE the migration): a customer, the admin and one cart item.
create temp table rehearsal_ids(k text primary key, id uuid, v numeric);
do $setup$
declare customer_id uuid; admin_id uuid; v public.product_variants;
begin
  select ur.user_id into customer_id from public.user_roles ur where ur.role = 'customer' order by ur.created_at limit 1;
  select ur.user_id into admin_id from public.user_roles ur where ur.role = 'admin' order by ur.created_at limit 1;
  select pv.* into v from public.product_variants pv join public.products pr on pr.id = pv.product_id
   where pv.is_active and pr.status = 'active' and pr.kind = 'standard' and pv.price >= 100 order by pv.price limit 1;
  insert into rehearsal_ids values ('customer', customer_id, null), ('admin', admin_id, null), ('variant', v.id, v.price);
end $setup$;

-- ===== phase 105 =====
-- Phase 105 · Voucher wallet: vouchers customers can see and pick at checkout.
-- What this does, in plain words:
--   1. Adds vouchers.show_to_customers (default off). Only vouchers the owner switches on are ever listed; any
--      other code still works when typed, exactly as in phase 103.
--   2. public.set_voucher_shown(target, shown): admin-only switch for that flag.
--   3. public.available_vouchers(items): for the signed-in customer, the shown vouchers that are active, in date,
--      not used up and not already used by them. With cart items it also says whether each one fits the cart and
--      the discount it would give, using the same checks as preview_voucher. Nothing is reserved or saved.
-- The discount on an order is still worked out only by create_order (phase 103). Safe to run more than once.

alter table public.vouchers add column if not exists show_to_customers boolean not null default false;

create or replace function private.set_voucher_shown(target uuid, shown boolean) returns public.vouchers
language plpgsql security definer set search_path = '' as $$
declare v public.vouchers;
begin
  if auth.uid() is null or not private.is_admin() then raise exception 'Admin access required.' using errcode = '42501'; end if;
  update public.vouchers set show_to_customers = coalesce(shown, false), updated_at = now() where id = target returning * into v;
  if v.id is null then raise exception 'Voucher not found.' using errcode = '22023'; end if;
  return v;
end $$;
revoke all on function private.set_voucher_shown(uuid, boolean) from public;
grant execute on function private.set_voucher_shown(uuid, boolean) to authenticated;
create or replace function public.set_voucher_shown(target uuid, shown boolean) returns public.vouchers
language sql security invoker set search_path = '' as $$ select private.set_voucher_shown(target, shown) $$;
revoke all on function public.set_voucher_shown(uuid, boolean) from public, anon;
grant execute on function public.set_voucher_shown(uuid, boolean) to authenticated;

create or replace function public.available_vouchers(items jsonb default '[]'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v public.vouchers; result jsonb := '[]'::jsonb; preview jsonb; reason text; used integer; mine integer;
begin
  if auth.uid() is null then return '[]'::jsonb; end if;
  for v in select * from public.vouchers where show_to_customers and is_active
             and (starts_at is null or starts_at <= now()) and (ends_at is null or ends_at > now())
           order by ends_at nulls last, created_at desc limit 30 loop
    select count(*) into used from public.voucher_redemptions r join public.orders o on o.id = r.order_id where r.voucher_id = v.id and o.status <> 'cancelled';
    continue when v.usage_limit is not null and used >= v.usage_limit;
    select count(*) into mine from public.voucher_redemptions r join public.orders o on o.id = r.order_id
     where r.voucher_id = v.id and r.customer_id = auth.uid() and o.status <> 'cancelled';
    continue when mine >= v.per_customer_limit;
    preview := null; reason := null;
    if jsonb_typeof(items) = 'array' and jsonb_array_length(items) > 0 then
      begin preview := public.preview_voucher(v.code, items);
      exception when others then reason := sqlerrm; end;
    end if;
    result := result || jsonb_build_object('code', v.code, 'description', v.description, 'type', v.discount_type, 'value', v.discount_value,
      'min_purchase', v.min_purchase, 'max_discount', v.max_discount, 'ends_at', v.ends_at, 'applies_to', v.applies_to,
      'fits', preview is not null, 'discount', preview->'discount', 'reason', reason);
  end loop;
  return result;
end $$;
revoke all on function public.available_vouchers(jsonb) from public, anon;
grant execute on function public.available_vouchers(jsonb) to authenticated;


-- ===== checks =====
-- Phase 105 checks: only shown vouchers are listed, with the cart fit worked out; only the admin can show them.
do $rehearsal$
declare report text := ''; ok boolean; list jsonb; v public.vouchers; hidden public.vouchers; big public.vouchers;
  customer_id uuid := (select id from rehearsal_ids where k = 'customer'); admin_id uuid := (select id from rehearsal_ids where k = 'admin');
  items jsonb := jsonb_build_array(jsonb_build_object('variant_id', (select id from rehearsal_ids where k = 'variant'), 'qty', 1));
begin
  perform set_config('request.jwt.claim.sub', admin_id::text, true); perform set_config('request.jwt.claims', json_build_object('sub', admin_id, 'role', 'authenticated')::text, true); perform set_config('role', 'authenticated', true);
  v := public.save_voucher(jsonb_build_object('code', 'REHEARSALSHOW', 'discount_type', 'fixed', 'discount_value', 20));
  hidden := public.save_voucher(jsonb_build_object('code', 'REHEARSALHIDE', 'discount_type', 'fixed', 'discount_value', 20));
  big := public.save_voucher(jsonb_build_object('code', 'REHEARSALMIN', 'discount_type', 'fixed', 'discount_value', 20, 'min_purchase', 99999));
  v := public.set_voucher_shown(v.id, true); perform public.set_voucher_shown(big.id, true);
  report := report || E'\n' || case when v.show_to_customers then 'PASS' else 'FAIL' end || '  admin can show a voucher';

  perform set_config('request.jwt.claim.sub', customer_id::text, true); perform set_config('request.jwt.claims', json_build_object('sub', customer_id, 'role', 'authenticated')::text, true);
  begin perform public.set_voucher_shown(hidden.id, true); report := report || E'\nFAIL  a customer could show a voucher';
  exception when others then report := report || E'\nPASS  customers cannot show vouchers (' || sqlerrm || ')'; end;
  list := public.available_vouchers(items);
  ok := exists (select 1 from jsonb_array_elements(list) x where x->>'code' = 'REHEARSALSHOW' and (x->>'fits')::boolean and (x->>'discount')::numeric = 20)
    and not exists (select 1 from jsonb_array_elements(list) x where x->>'code' = 'REHEARSALHIDE');
  report := report || E'\n' || case when ok then 'PASS' else 'FAIL' end || '  shown voucher listed and fits the cart; hidden one not listed';
  ok := exists (select 1 from jsonb_array_elements(list) x where x->>'code' = 'REHEARSALMIN' and not (x->>'fits')::boolean and x->>'reason' like '%minimum%');
  report := report || E'\n' || case when ok then 'PASS' else 'FAIL' end || '  voucher above the cart minimum listed as not fitting, with the reason';
  list := public.available_vouchers();
  report := report || E'\n' || case when jsonb_array_length(list) >= 2 then 'PASS' else 'FAIL' end || '  works without cart items';

  perform set_config('request.jwt.claim.sub', '', true); perform set_config('request.jwt.claims', '{"role":"anon"}', true); perform set_config('role', 'anon', true);
  begin list := public.available_vouchers(); report := report || E'\nFAIL  visitors (not logged in) could call it';
  exception when others then report := report || E'\nPASS  visitors cannot call it'; end;
  perform set_config('role', 'postgres', true);
  raise exception 'REHEARSAL REPORT (nothing was saved)%', report;
end $rehearsal$;
